1	// Port of PyYAML's resolver.py (BaseResolver + Resolver).
2	//
3	// Every implicit-resolver regex is replaced by a hand-written character
4	// scanner; the original PyYAML pattern (re.X whitespace stripped) sits in a
5	// comment above each one. The registration order below is PyYAML's own —
6	// bool, float, int, merge, null, timestamp, value, yaml — and resolve() walks
7	// the bucket for value[0] in exactly that order, so a value such as '1' hits
8	// the float matcher before the int matcher.
9	
10	import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
11	import { DIGITS, HEX_DIGITS, SPACES } from './chars.mjs';
12	
13	export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
14	export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
15	export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';
16	
17	const NON_ZERO_DIGITS = '123456789';
18	const SEXAGESIMAL_LEAD = '012345';
19	const DIGITS_ = DIGITS + '_';
20	const BINARY_ = '01_';
21	const OCTAL_ = '01234567_';
22	const HEX_DIGITS_ = HEX_DIGITS + '_';
23	
24	// --- scanning primitives ---------------------------------------------------
25	
26	/** The character at `i`, or '' past the end (never a member of a char set). */
27	const at = (s, i) => (i < s.length ? s[i] : '');
28	
29	/** `ch` is one of `set` — guarding against the '' that `at` yields at EOS. */
30	const has = (set, ch) => ch !== '' && set.includes(ch);
31	
32	/** `[-+]?` */
33	function optSign(s, i) {
34	  const ch = at(s, i);
35	  return (ch === '-' || ch === '+') ? i + 1 : i;
36	}
37	
38	/** `[<set>]*` — greedy, never fails. */
39	function many(s, i, set) {
40	  let j = i;
41	  while (j < s.length && set.includes(s[j])) j += 1;
42	  return j;
43	}
44	
45	/** Exactly `n` digits, or -1. */
46	function fixedDigits(s, i, n) {
47	  for (let k = 0; k < n; k += 1) if (!has(DIGITS, at(s, i + k))) return -1;
48	  return i + n;
49	}
50	
51	/** `[0-9][0-9]?`, or -1. Greedy is safe: every follower here is a non-digit. */
52	function shortDigits(s, i) {
53	  if (!has(DIGITS, at(s, i))) return -1;
54	  return has(DIGITS, at(s, i + 1)) ? i + 2 : i + 1;
55	}
56	
57	/** `(?:[eE][-+][0-9]+)?` — the sign is mandatory, so '1.5e3' is NOT a float. */
58	function optExponent(s, i) {
59	  const ch = at(s, i);
60	  if (ch !== 'e' && ch !== 'E') return i;
61	  let j = i + 1;
62	  const sign = at(s, j);
63	  if (sign !== '-' && sign !== '+') return i;
64	  j += 1;
65	  if (!has(DIGITS, at(s, j))) return i;
66	  return many(s, j + 1, DIGITS);
67	}
68	
69	/** `(?::[0-5]?[0-9])+` — returns the end index, or -1 if no group matched. */
70	function sexagesimalGroups(s, i) {
71	  let j = i;
72	  let count = 0;
73	  while (at(s, j) === ':') {
74	    let k = j + 1;
75	    if (!has(DIGITS, at(s, k))) break;
76	    if (SEXAGESIMAL_LEAD.includes(at(s, k)) && has(DIGITS, at(s, k + 1))) k += 2;
77	    else k += 1;
78	    j = k;
79	    count += 1;
80	  }
81	  return count > 0 ? j : -1;
82	}
83	
84	// --- the implicit-resolver matchers ---------------------------------------
85	
86	// tag:yaml.org,2002:bool
87	// ^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$
88	const BOOL_VALUES = [
89	  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
90	  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
91	  'on', 'On', 'ON', 'off', 'Off', 'OFF',
92	];
93	function matchBool(s) {
94	  return BOOL_VALUES.includes(s);
95	}
96	
97	// tag:yaml.org,2002:float
98	// ^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
99	//    |\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?
100	//    |[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
101	//    |[-+]?\.(?:inf|Inf|INF)
102	//    |\.(?:nan|NaN|NAN))$
103	// The second branch demands a digit immediately after the dot: the reference
104	// binary resolves '._' and '._5' as str, but '.5_' as float.
105	
106	/** `[-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?` */
107	function floatAlt1(s) {
108	  let i = optSign(s, 0);
109	  if (!has(DIGITS, at(s, i))) return false;
110	  i = many(s, i + 1, DIGITS_);
111	  if (at(s, i) !== '.') return false;
112	  i = many(s, i + 1, DIGITS_);
113	  return optExponent(s, i) === s.length;
114	}
115	
116	/** `\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?` */
117	function floatAlt2(s) {
118	  if (at(s, 0) !== '.') return false;
119	  if (!has(DIGITS, at(s, 1))) return false;
120	  const i = many(s, 2, DIGITS_);
121	  return optExponent(s, i) === s.length;
122	}
123	
124	/** `[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*` */
125	function floatAlt3(s) {
126	  let i = optSign(s, 0);
127	  if (!has(DIGITS, at(s, i))) return false;
128	  i = many(s, i + 1, DIGITS_);
129	  i = sexagesimalGroups(s, i);
130	  if (i < 0 || at(s, i) !== '.') return false;
131	  return many(s, i + 1, DIGITS_) === s.length;
132	}
133	
134	/** `[-+]?\.(?:inf|Inf|INF)` */
135	function floatAlt4(s) {
136	  const i = optSign(s, 0);
137	  if (at(s, i) !== '.') return false;
138	  const rest = s.slice(i + 1);
139	  return rest === 'inf' || rest === 'Inf' || rest === 'INF';
140	}
141	
142	/** `\.(?:nan|NaN|NAN)` */
143	function floatAlt5(s) {
144	  return s === '.nan' || s === '.NaN' || s === '.NAN';
145	}
146	
147	function matchFloat(s) {
148	  return floatAlt1(s) || floatAlt2(s) || floatAlt3(s) || floatAlt4(s) || floatAlt5(s);
149	}
150	
151	// tag:yaml.org,2002:int
152	// ^(?:[-+]?0b[0-1_]+
153	//    |[-+]?0[0-7_]+
154	//    |[-+]?(?:0|[1-9][0-9_]*)
155	//    |[-+]?0x[0-9a-fA-F_]+
156	//    |[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$
157	
158	/** `[-+]?0b[0-1_]+` */
159	function intAlt1(s) {
160	  let i = optSign(s, 0);
161	  if (at(s, i) !== '0' || at(s, i + 1) !== 'b') return false;
162	  i += 2;
163	  if (!has(BINARY_, at(s, i))) return false;
164	  return many(s, i + 1, BINARY_) === s.length;
165	}
166	
167	/** `[-+]?0[0-7_]+` */
168	function intAlt2(s) {
169	  let i = optSign(s, 0);
170	  if (at(s, i) !== '0') return false;
171	  i += 1;
172	  if (!has(OCTAL_, at(s, i))) return false;
173	  return many(s, i + 1, OCTAL_) === s.length;
174	}
175	
176	/** `[-+]?(?:0|[1-9][0-9_]*)` */
177	function intAlt3(s) {
178	  const i = optSign(s, 0);
179	  if (at(s, i) === '0') return i + 1 === s.length;
180	  if (!has(NON_ZERO_DIGITS, at(s, i))) return false;
181	  return many(s, i + 1, DIGITS_) === s.length;
182	}
183	
184	/** `[-+]?0x[0-9a-fA-F_]+` */
185	function intAlt4(s) {
186	  let i = optSign(s, 0);
187	  if (at(s, i) !== '0' || at(s, i + 1) !== 'x') return false;
188	  i += 2;
189	  if (!has(HEX_DIGITS_, at(s, i))) return false;
190	  return many(s, i + 1, HEX_DIGITS_) === s.length;
191	}
192	
193	/** `[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+` */
194	function intAlt5(s) {
195	  let i = optSign(s, 0);
196	  if (!has(NON_ZERO_DIGITS, at(s, i))) return false;
197	  i = many(s, i + 1, DIGITS_);
198	  i = sexagesimalGroups(s, i);
199	  return i >= 0 && i === s.length;
200	}
201	
202	function matchInt(s) {
203	  return intAlt1(s) || intAlt2(s) || intAlt3(s) || intAlt4(s) || intAlt5(s);
204	}
205	
206	// tag:yaml.org,2002:merge — ^(?:<<)$
207	function matchMerge(s) {
208	  return s === '<<';
209	}
210	
211	// tag:yaml.org,2002:null — ^(?:~|null|Null|NULL|)$
212	function matchNull(s) {
213	  return s === '~' || s === 'null' || s === 'Null' || s === 'NULL' || s === '';
214	}
215	
216	// tag:yaml.org,2002:timestamp
217	// ^(?:[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]
218	//    |[0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?
219	//     (?:[Tt]|[ \t]+)[0-9][0-9]?
220	//     :[0-9][0-9]:[0-9][0-9](?:\.[0-9]*)?
221	//     (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))?)$
222	
223	/** `[0-9]{4}-[0-9]{2}-[0-9]{2}` */
224	function timestampAlt1(s) {
225	  let i = fixedDigits(s, 0, 4);
226	  if (i < 0 || at(s, i) !== '-') return false;
227	  i = fixedDigits(s, i + 1, 2);
228	  if (i < 0 || at(s, i) !== '-') return false;
229	  i = fixedDigits(s, i + 1, 2);
230	  return i === s.length;
231	}
232	
233	/** The full date-time branch. */
234	function timestampAlt2(s) {
235	  let i = fixedDigits(s, 0, 4);
236	  if (i < 0 || at(s, i) !== '-') return false;
237	  i = shortDigits(s, i + 1);
238	  if (i < 0 || at(s, i) !== '-') return false;
239	  i = shortDigits(s, i + 1);
240	  if (i < 0) return false;
241	  // (?:[Tt]|[ \t]+)
242	  const sep = at(s, i);
243	  if (sep === 'T' || sep === 't') i += 1;
244	  else if (has(SPACES, sep)) i = many(s, i + 1, SPACES);
245	  else return false;
246	  i = shortDigits(s, i);
247	  if (i < 0 || at(s, i) !== ':') return false;
248	  i = fixedDigits(s, i + 1, 2);
249	  if (i < 0 || at(s, i) !== ':') return false;
250	  i = fixedDigits(s, i + 1, 2);
251	  if (i < 0) return false;
252	  // (?:\.[0-9]*)?
253	  if (at(s, i) === '.') i = many(s, i + 1, DIGITS);
254	  // (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-9][0-9])?))? — the whole group is
255	  // optional, so a failed timezone leaves `i` where the seconds ended.
256	  const j = many(s, i, SPACES);
257	  const tz = at(s, j);
258	  if (tz === 'Z') {
259	    i = j + 1;
260	  } else if (tz === '-' || tz === '+') {
261	    let k = shortDigits(s, j + 1);
262	    if (k >= 0) {
263	      if (at(s, k) === ':') {
264	        const m = fixedDigits(s, k + 1, 2);
265	        if (m >= 0) k = m;
266	      }
267	      i = k;
268	    }
269	  }
270	  return i === s.length;
271	}
272	
273	function matchTimestamp(s) {
274	  return timestampAlt1(s) || timestampAlt2(s);
275	}
276	
277	// tag:yaml.org,2002:value — ^(?:=)$
278	function matchValue(s) {
279	  return s === '=';
280	}
281	
282	// tag:yaml.org,2002:yaml — ^(?:!|&|\*)$
283	function matchYaml(s) {
284	  return s === '!' || s === '&' || s === '*';
285	}
286	
287	// --- registration ----------------------------------------------------------
288	
289	// Python's `regexp.match(value)` against a pattern ending in `$`: `$` matches
290	// at the end of the string *or* just before a single trailing newline.
291	const anchored = (exact) => (value) =>
292	  exact(value) || (value.endsWith('\n') && exact(value.slice(0, -1)));
293	
294	/** char -> ordered [{tag, match}]; key '' is the empty scalar, null the wildcard. */
295	const IMPLICIT_RESOLVERS = new Map();
296	
297	function addImplicitResolver(tag, match, first) {
298	  const keys = first === null ? [null] : first;
299	  for (const ch of keys) {
300	    if (!IMPLICIT_RESOLVERS.has(ch)) IMPLICIT_RESOLVERS.set(ch, []);
301	    IMPLICIT_RESOLVERS.get(ch).push({ tag, match: anchored(match) });
302	  }
303	}
304	
305	addImplicitResolver('tag:yaml.org,2002:bool', matchBool, [...'yYnNoOtTfF']);
306	addImplicitResolver('tag:yaml.org,2002:float', matchFloat, [...'-+0123456789.']);
