320	      super(...args);
321	      this.resolverExactPaths = [];
322	      this.resolverPrefixPaths = [];
323	    }
324	
325	    descendResolver(currentNode, currentIndex) {
326	      if (this.yamlPathResolvers.length === 0) return;
327	      const exactPaths = new Map();
328	      const prefixPaths = [];
329	      if (currentNode) {
330	        const depth = this.resolverPrefixPaths.length;
331	        for (const entry of this.resolverPrefixPaths[depth - 1]) {
332	          if (this.checkResolverPrefix(depth, entry.path, entry.kind, currentNode, currentIndex)) {
333	            if (entry.path.length > depth) prefixPaths.push(entry);
334	            else exactPaths.set(entry.kind, entry.tag);
335	          }
336	        }
337	      } else {
338	        for (const entry of this.yamlPathResolvers) {
339	          if (entry.path.length === 0) exactPaths.set(entry.kind, entry.tag);
340	          else prefixPaths.push(entry);
341	        }
342	      }
343	      this.resolverExactPaths.push(exactPaths);
344	      this.resolverPrefixPaths.push(prefixPaths);
345	    }
346	
347	    ascendResolver() {
348	      if (this.yamlPathResolvers.length === 0) return;
349	      this.resolverExactPaths.pop();
350	      this.resolverPrefixPaths.pop();
351	    }
352	
353	    checkResolverPrefix(depth, path, kind, currentNode, currentIndex) {
354	      const [nodeCheck, indexCheck] = path[depth - 1];
355	      if (typeof nodeCheck === 'string') {
356	        if (currentNode.tag !== nodeCheck) return false;
357	      } else if (nodeCheck !== null) {
358	        if (!(currentNode instanceof nodeCheck)) return false;
359	      }
360	      if (indexCheck === true && currentIndex !== null) return false;
361	      if ((indexCheck === false || indexCheck === null) && currentIndex === null) return false;
362	      if (typeof indexCheck === 'string') {
363	        if (!(currentIndex instanceof ScalarNode && indexCheck === currentIndex.value)) return false;
364	      } else if (typeof indexCheck === 'number' || typeof indexCheck === 'bigint') {
365	        if (indexCheck !== currentIndex) return false;
366	      }
367	      return true;
368	    }
369	
370	    resolve(kind, value, implicit) {
371	      if (kind === ScalarNode && implicit[0]) {
372	        let resolvers;
373	        if (value === '') resolvers = this.yamlImplicitResolvers.get('') || [];
