375	        const wildcardResolvers = this.yamlImplicitResolvers.get(null) || [];
376	        for (const { tag, match } of [...resolvers, ...wildcardResolvers]) {
377	          if (match(value)) return tag;
378	        }
379	        implicit = implicit[1];
380	      }
381	      if (this.yamlPathResolvers.length !== 0) {
382	        const exactPaths = this.resolverExactPaths[this.resolverExactPaths.length - 1];
383	        if (exactPaths.has(kind)) return exactPaths.get(kind);
384	        if (exactPaths.has(null)) return exactPaths.get(null);
385	      }
386	      if (kind === ScalarNode) return this.DEFAULT_SCALAR_TAG;
387	      else if (kind === SequenceNode) return this.DEFAULT_SEQUENCE_TAG;
388	      else if (kind === MappingNode) return this.DEFAULT_MAPPING_TAG;
389	      return undefined;
390	    }
391	  }
392	
393	  // PyYAML holds these as class attributes; the prototype is the closest thing.
394	  Resolver.prototype.yamlImplicitResolvers = IMPLICIT_RESOLVERS;
395	  // PyYAML keys yaml_path_resolvers by a (path, kind) tuple, which JS cannot
396	  // do; a list of {path, kind, tag} is the same information. Nothing in the
397	  // exercised subset calls add_path_resolver, so this stays empty and both
398	  // descendResolver and ascendResolver short-circuit to no-ops.
399	  Resolver.prototype.yamlPathResolvers = [];
400	  Resolver.prototype.DEFAULT_SCALAR_TAG = DEFAULT_SCALAR_TAG;
401	  Resolver.prototype.DEFAULT_SEQUENCE_TAG = DEFAULT_SEQUENCE_TAG;
402	  Resolver.prototype.DEFAULT_MAPPING_TAG = DEFAULT_MAPPING_TAG;
403	  return Resolver;
404	};
